import{esc,table,num}from'./ui.mjs';
import{finite}from'./algorithms.mjs';
const RULES=[
 {category:'物理取值',name:'产油、产水、注水体积非负',formula:'V油 ≥ 0；V水 ≥ 0；V注 ≥ 0',note:'逐字段检查有效数值。缺失不按零处理；单位沿用源数据口径。',fields:['oil_volume_sm3','water_volume_sm3','water_injection_volume_sm3'],any:true,level:'L0 阻断'},
 {category:'物理取值',name:'含水比例范围',formula:'0 ≤ fw ≤ 1',note:'fw为无量纲比例，0至1对应0%至100%。',fields:['water_cut'],level:'L0 阻断'},
 {category:'物理取值',name:'每日开井时长',formula:'0 ≤ 开井时长 ≤ 24.01 小时/日',note:'名义上限24小时；当前实现保留0.01小时（36秒）的数值容差。',fields:['on_stream_hours'],level:'L0 阻断'},
 {category:'配置取值范围',name:'岩石体积密度 RHOB',formula:'0.5 ≤ RHOB ≤ 5 克/立方厘米',note:'平台当前配置的宽范围筛查阈值，不是所有岩性通用的物理定律。',fields:['RHOB'],level:'L0 阻断'},
 {category:'物理一致性',name:'油水体积与含水比例一致',formula:'|fw − V水/(V油 + V水)| ≤ 0.001',note:'油、水体积和fw均有效且V油+V水>0时检查；容差0.001为0.1个百分点，体积必须同一口径。',fields:['oil_volume_sm3','water_volume_sm3','water_cut'],level:'L0 阻断'},
 {category:'跨专业对齐',name:'测井与岩心深度一致',formula:'|测井深度 − 岩心深度| ≤ 2 米',note:'超过2米触发阻断；属于专业记录对齐约束。',fields:['log_depth_m','core_depth_m'],level:'L0 阻断'},
 {category:'跨专业一致性',name:'测井与岩心孔隙度差异',formula:'|φ测井 − φ岩心| ≤ 0.04',note:'差异超过0.04（4个百分点）只作警示，不计入L0物理规则阻断记录。',fields:['phi_log','phi_core'],level:'L1 警示'},
 {category:'测量待核查',name:'井下压力为零',formula:'AVG_DOWNHOLE_PRESSURE = 0 → 待核查',note:'保留零值并警示；当前未按未核定的压力单位设定统一压力上下限。',fields:['AVG_DOWNHOLE_PRESSURE'],level:'L1 警示'}
];
export function renderQualityRuleNotes(rows,qc){const rules=RULES.map(r=>({...r,available:rows.some(row=>r.any?r.fields.some(f=>finite(row[f])):r.fields.every(f=>finite(row[f])))}));const evidence=qc.blocking.flatMap(r=>r.reasons.map(reason=>({sample:String(r.key??'第'+(r.index+1)+'行'),reason,values:JSON.stringify(Object.fromEntries(Object.entries(rows[r.index]??{}).filter(([k])=>RULES.some(x=>x.fields.includes(k)))))})));
return`<details class="quality-rule-notes" id="quality-rule-notes" open><summary>具体物理规则、专业约束与当前触发依据</summary><p>“规则阻断”统计当前输入中触发L0强约束的记录数：${num(qc.blocking.length)} 条。同一记录触发多项规则只计一次。以下规则按已有有效字段执行；缺失值不会被判作“通过”。</p><div class="table-scroll"><table class="data-table"><thead><tr><th>类别 / 规则</th><th>具体阈值或公式</th><th>适用条件与说明</th><th>等级 / 当前适用性</th></tr></thead><tbody>${rules.map(r=>`<tr><td><small>${esc(r.category)}</small><b>${esc(r.name)}</b></td><td class="rule-formula">${esc(r.formula)}</td><td>${esc(r.note)}</td><td><b>${r.level}</b><span class="rule-availability ${r.available?'available':'unavailable'}">${r.available?'存在可检查数值':'无完整有效字段，不执行'}</span></td></tr>`).join('')}</tbody></table></div><div class="rule-data-checks"><b>数据完整性检查（单独列示）</b><p>重复主键：${qc.duplicates.length} 条，属于L0数据约束；缺失单元格：${qc.missingCells} 个，属于完整性提示；L1警示：${qc.warnings.length} 条。它们不属于物理定律。重复主键单独计数，不包含在上方“规则阻断”的物理/专业约束记录数中。</p></div><div class="rule-evidence"><h3>当前L0触发记录与原因</h3>${evidence.length?table(evidence,[{key:'sample',label:'记录标识',text:true},{key:'reason',label:'实际触发原因',text:true},{key:'values',label:'原始约束字段值',text:true}],{limit:evidence.length}):'<p>当前没有触发上述L0物理/专业约束；这不表示所有字段齐全或已通过专家复核。</p>'}</div><p class="rule-scope-note">以上阈值对应当前网页质控实现；GRIN补全候选的非负值、短缺口与适用变量闸门在“缺失补全”页单独展示。</p></details>`}
